// Generator timing settings
// 223: Maximum operating time of generator (0.1 hours)
// 224: Generator cooling time (0.1 hours)

msg.baseAddr = 223;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 223,
    quantity: 2
};

return msg;

// Generator charge settings
// 226: Generator charging starting capacity point (1%)
// 227: Generator charges the battery current (1A)

msg.baseAddr = 226;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 226,
    quantity: 2
};

return msg;

// Grid charge settings and enables
// 229: Grid charging start capacity point (1%)
// 230: Grid charge the battery current (1A)
// 231: Generator charge enable
// 232: Grid charge enable

msg.baseAddr = 229;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 229,
    quantity: 4
};

return msg;

// Build BatteryChargeSourceConfigState from multiple Modbus reads.
//
// Registers:
// 223: Maximum operating time of generator (0.1 hours)
// 224: Generator cooling time (0.1 hours)
// 226: Generator charging starting capacity point (1%)
// 227: Generator charges the battery current (1A)
// 229: Grid charging start capacity point (1%)
// 230: Grid charge the battery current (1A)
// 231: Generator charge enable
// 232: Grid charge enable

let raw = msg.payload;

// node-red-contrib-modbus often sends { data: [...], buffer: ... }
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

// Skip string errors
if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

// Determine which block we just read
let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("BatteryChargeSourceConfigState: missing base address on msg");
    return null;
}

// ---- Store partials in flow context ----

// Generator timing 223-224
if (baseAddr === 223) {
    const maxRunTimeRaw = data[0] || 0;    // 0.1 hours
    const coolingTimeRaw = data[1] || 0;   // 0.1 hours

    flow.set("bchg_part_gen_timing", {
        maxRunTimeHours: Math.round(maxRunTimeRaw * 0.1 * 10) / 10,
        coolingTimeHours: Math.round(coolingTimeRaw * 0.1 * 10) / 10
    });
}

// Generator charge 226-227
else if (baseAddr === 226) {
    const startSoc = data[0] || 0;         // 1%
    const chargeCurrent = data[1] || 0;    // 1A

    flow.set("bchg_part_gen_charge", {
        startSocPercent: startSoc,
        chargeCurrentA: chargeCurrent
    });
}

// Grid settings 229-232
else if (baseAddr === 229) {
    const gridStartSoc = data[0] || 0;       // 229: 1%
    const gridChargeCurrent = data[1] || 0;  // 230: 1A
    const genEnabled = data[2] || 0;         // 231: bool
    const gridEnabled = data[3] || 0;        // 232: bool

    flow.set("bchg_part_grid", {
        gridStartSocPercent: gridStartSoc,
        gridChargeCurrentA: gridChargeCurrent,
        genEnabled: genEnabled === 1,
        gridEnabled: gridEnabled === 1
    });
}
else {
    return null;
}

// ---- Try to assemble full state ----

const genTimingPart = flow.get("bchg_part_gen_timing");
const genChargePart = flow.get("bchg_part_gen_charge");
const gridPart = flow.get("bchg_part_grid");

// Require all parts
if (!genTimingPart || !genChargePart || !gridPart) {
    return null;
}

// Resolve identifiers
const gatewayId = msg.gatewayId
    || global.get("GATEWAY_ID")
    || env.get("GATEWAY_ID")
    || "EC100-GW-001";

const inverterSN = msg.inverterSerialNumber
    || global.get("INVERTER_SN")
    || env.get("INVERTER_SN")
    || "Unknown";

const state = {
    kind: "BatteryChargeSourceConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,

    generator: {
        enabled: gridPart.genEnabled,
        startSocPercent: genChargePart.startSocPercent,
        chargeCurrentA: genChargePart.chargeCurrentA,
        maxRunTimeHours: genTimingPart.maxRunTimeHours,
        coolingTimeHours: genTimingPart.coolingTimeHours
    },

    grid: {
        enabled: gridPart.gridEnabled,
        startSocPercent: gridPart.gridStartSocPercent,
        chargeCurrentA: gridPart.gridChargeCurrentA
    }
};

// Clear partials for next cycle
flow.set("bchg_part_gen_timing", null);
flow.set("bchg_part_gen_charge", null);
flow.set("bchg_part_grid", null);

// Keep snapshot in flow
flow.set("batteryChargeSourceConfigSnapshot", state);

// Put result on msg
msg.payload = state;
msg.state = state;

return msg;
